declare(strict_types=1);$root=dirname(__DIR__);function limit_assert(bool $c,string $m):void{if(!$c){fwrite(STDERR,"[FAIL] $m\n");exit(1);}}$bootstrap=(string)file_get_contents($root.'/app/bootstrap.php');$web=(string)file_get_contents($root.'/web.config');$userIni=$root.'/.user.ini';$migration=$root.'/database/028_document_version_500mib_limit.sql';limit_assert(str_contains($bootstrap,'const PORTAL_DOCUMENT_HASH_MAX_BYTES = 524288000;'),'application limit is not 500 MiB');limit_assert(is_file($userIni),'protected PHP upload config is missing');$ini=(string)file_get_contents($userIni);foreach(['upload_max_filesize=500M','post_max_size=502M','memory_limit=128M'] as $n)limit_assert(str_contains(str_replace(' ','',$ini),$n),'PHP upload contract missing '.$n);limit_assert(str_contains($web,'maxAllowedContentLength="526385152"'),'IIS request limit is not 502 MiB');limit_assert(is_file($migration),'migration 028 is missing');$sql=(string)file_get_contents($migration);foreach(['524288000','CK_document_version_contents_size','portal_capture_current_document_version','portal_backfill_document_version_content','@ledger=1','@post_invalid','@pre_invalid','ec73c1150e3f1cd24600b84c007c2794b648d02073ba2f6c0ee829702ea15be0','2fa3c689cd658c51ac0041a4f5b047c062c9ec7016002df933080f58eb6cc7a7','028_document_version_500mib_limit.sql'] as $n)limit_assert(str_contains($sql,$n),'migration 028 missing '.$n);echo "[OK] PHP, IIS, application and SQL document limits are aligned at 500 MiB.\n";
